                    "head_after": readonly_head_after,
                    "tracked_before": readonly_tracked_before,
                    "tracked_after": readonly_tracked_after,
                    "diff_names": git("diff", "--name-only", cwd=ROOT, check=False).stdout,
                    "diff_stat": git("diff", "--stat", cwd=ROOT, check=False).stdout,
                    "diff_porcelain": readonly_tracked_after,
                    "check_types": [str(c.get("type")) for c in checks if isinstance(c, dict)],
                    "cwd": str(ROOT),
                }
                result["blockers"].append("readonly_tracked_repo_mutation_detected")
            result["checks"] = check_results
            if _native_decision_contract_required(job):
                _promote_native_decision_from_semantic_extract(result, check_results)
            if (
                result.get("required_deliverables")
                and result.get("deliverable_specs")
            ):
                try:
                    result["deliverables"] = (
                        materialize_deliverables(
                            result.get(
                                "required_deliverables"
                            ),
                            result.get(
                                "deliverable_specs"
                            ),
                            check_results,
                        )
                    )
                except ValueError as exc:
                    result["blockers"].append(
                        "deliverable_materialization_failed:"
                        + str(exc)
                    )
            result["files_changed"] = []
            result["tests"] = "PASS" if check_results and all(x["status"] == "PASS" for x in check_results) else "FAIL"
            result["quality_gate"] = "PASS" if not result["blockers"] else "FAIL"
            result["work_completion"] = "COMPLETE" if not result["blockers"] else "INCOMPLETE"
            def evaluate_objective_criteria(criteria, check_results, blockers):
                """Fail-closed evaluation of explicit check evidence."""
                evidence = []

                for criterion in criteria:
                    index = criterion["check_index"]
                    key = criterion["evidence_key"]
                    expected = criterion["expected_value"]

                    check = (
                        check_results[index]
                        if index < len(check_results)
                        else {}
                    )

                    actual = check.get(key)

                    satisfied = (
                        check.get("status") == "PASS"
                        and key in check
                        and type(actual) is type(expected)
                        and actual == expected
                    )

                    evidence.append({
                        "id": criterion["id"],
                        "check_index": index,
                        "evidence_key": key,
                        "satisfied": satisfied,
                    })

                certified = (
                    bool(evidence)
                    and all(item["satisfied"] for item in evidence)
                    and not blockers
                )

                return (
                    "OBJECTIVE_CERTIFIED"
                    if certified
                    else "OBJECTIVE_PENDING",
                    evidence,
                )

            criteria = job.get("acceptance_criteria")
