    value: Any,
    *,
    max_length: int = 256,
) -> str | None:
    if not isinstance(value, str):
        return None

    value = value.replace("\x00", "").strip()

    if not value:
        return None

    return redact_sensitive_text(
        value,
        max_length=max_length,
    )


def _safe_output(value: Any) -> str:
    if not isinstance(value, str):
        return ""

    rows: list[str] = []

    for raw in value.replace("\x00", "").splitlines():
        if has_sensitive_marker(raw):
            rows.append("[REDACTED]")
            continue

        rows.append(
            redact_sensitive_text(
                raw,
                max_length=1000,
            )
        )

    text = "\n".join(rows)

    if len(text.encode("utf-8")) > MAX_OUTPUT_BYTES:
        text = text[-MAX_OUTPUT_BYTES:]

    return text


def _assertion_lines(output: str) -> list[str]:
    rows: list[str] = []

    for raw in output.splitlines():
        line = raw.strip()
        upper = line.upper()

        interesting = (
            line.startswith("E   ")
            or "ASSERTIONERROR" in upper
            or upper.startswith("FAILED ")
            or " ERROR " in f" {upper} "
            or "MISMATCH" in upper
        )

        if not interesting:
            continue

        safe = _safe_label(
            line,
            max_length=500,
        )

        if safe:
            rows.append(safe)

        if len(rows) >= MAX_ASSERTION_LINES:
            break

    return rows


def _safe_string_list(
    value: Any,
    *,
    max_items: int = 100,
    max_length: int = 512,
) -> list[str]:
    if not isinstance(value, list):
        return []

    rows: list[str] = []

    for item in value[:max_items]:
        safe = _safe_label(
            item,
            max_length=max_length,
        )

        if safe:
            rows.append(safe)

    return rows


def collect(job_id: str) -> dict[str, Any]:
    if not JOB_ID_RE.fullmatch(job_id):
        raise ValueError("RESULT_DETAIL_JOB_ID_INVALID")

    if (
        RESULTS.is_symlink()
        or not RESULTS.is_dir()
    ):
        raise ValueError(
            "RESULT_DETAIL_RESULTS_DIR_UNAVAILABLE"
        )

    path = RESULTS / f"{job_id}.json"

    if (
        path.parent != RESULTS
        or path.is_symlink()
        or not path.is_file()
    ):
        raise ValueError(
            "RESULT_DETAIL_RESULT_NOT_FOUND"
        )

    stat = path.stat()

    if stat.st_size > MAX_RESULT_BYTES:
        raise ValueError(
            "RESULT_DETAIL_RESULT_TOO_LARGE"
        )

    with path.open(
        "r",
        encoding="utf-8",
    ) as handle:
        payload = json.load(handle)

    if not isinstance(payload, dict):
        raise ValueError(
            "RESULT_DETAIL_RESULT_NOT_OBJECT"
        )

    checks = payload.get("checks")
    checks = checks if isinstance(checks, list) else []

    failed_checks: list[dict[str, Any]] = []

    for raw in checks:
        if not isinstance(raw, dict):
            continue

        if str(
            raw.get("status") or ""
        ).strip().upper() != "FAIL":
            continue

        output = _safe_output(
            raw.get("output")
        )

        returncode = raw.get("returncode")

        if (
            isinstance(returncode, bool)
            or not isinstance(returncode, int)
        ):
            returncode = None

        failed_checks.append(
            {
                "type": _safe_label(
                    raw.get("type"),
                    max_length=128,
                ),
                "status": "FAIL",
                "returncode": returncode,
                "output": output,
                "assertion_lines": (
                    _assertion_lines(output)
                ),
            }
        )

        if (
            len(failed_checks)
            >= MAX_FAILED_CHECKS
        ):
            break

    percent = payload.get(
        "percent_complete"
    )

    if (
        isinstance(percent, bool)
        or not isinstance(percent, (int, float))
        or percent < 0
        or percent > 100
    ):
        percent = None

    production_touched = payload.get(
        "production_touched"
    )

    if not isinstance(
        production_touched,
        bool,
    ):
        production_touched = None

    return {
        "schema": (
            "edarsahub.worker-result-detail-read.v1"
        ),
        "mode": "READ_ONLY",
        "status": "PASS",
        "source_job_id": job_id,
        "result_status": _safe_label(
            payload.get("status"),
        ),
        "quality_gate": _safe_label(
            payload.get("quality_gate"),
        ),
        "tests": _safe_label(
            payload.get("tests"),
        ),
        "certification": _safe_label(
            payload.get("certification"),
        ),
        "work_completion": _safe_label(
            payload.get("work_completion"),
        ),
        "percent_complete": percent,
        "blockers": _safe_string_list(
            payload.get("blockers"),
            max_length=500,
        ),
        "files_changed": _safe_string_list(
            payload.get("files_changed"),
            max_length=512,
        ),
        "failed_checks": failed_checks,
        "failed_check_count": len(
            failed_checks
        ),
        "production_touched": (
            production_touched
        ),
        "production_allowed": False,
    }


def main() -> int:
    parser = argparse.ArgumentParser()

    parser.add_argument(
        "--job-id",
        required=True,
    )

    args = parser.parse_args()

    try:
        payload = collect(args.job_id)

        print(
            json.dumps(
                payload,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            )
        )

        return 0

    except (
        OSError,
        ValueError,
        RuntimeError,
        json.JSONDecodeError,
    ) as exc:

        print(
            json.dumps(
                {
                    "schema": (
                        "edarsahub."
                        "worker-result-detail-read.v1"
                    ),
                    "mode": "READ_ONLY",
                    "status": "FAIL",
                    "error_code": type(exc).__name__,
                    "production_allowed": False,
                },
                sort_keys=True,
            )
        )

        return 1


if __name__ == "__main__":
    raise SystemExit(main())

"""Security and ingress contract for WORKER_RESULT_DETAIL_READ."""
from __future__ import annotations

import json
from pathlib import Path

import pytest

from modules.worker_ingress import service
from modules.worker_ingress.semantic_capabilities import (
    registered_capabilities,
)
from tools.mirror_sync import (
    gate_chain_publisher as publisher,
)
from tools.mirror_sync import (
    universal_job_bridge as bridge,
)
from tools.mirror_sync import (
    worker_result_detail_read as detail,
)


SOURCE_JOB = (
    "EDARSAHUB-WORKER-TEST-"
    "FAILED-R1"
)


def _write_result(
    directory: Path,
    payload: dict,
):
    directory.mkdir(
        parents=True,
        exist_ok=True,
    )

    (
        directory
        / f"{SOURCE_JOB}.json"
    ).write_text(
        json.dumps(payload),
        encoding="utf-8",
    )


def test_detail_reader_returns_only_bounded_failure_evidence(
    tmp_path,
    monkeypatch,
):
    results = tmp_path / "results"

    _write_result(
        results,
        {
            "schema": "edarsahub.worker-result.v2",
            "job_id": SOURCE_JOB,
            "status": "GIT_TESTS_FAILED",
            "quality_gate": "FAIL",
            "tests": "FAIL",
            "certification": "NOT_CERTIFIED",
            "work_completion": "NOT_CERTIFIED",
            "percent_complete": 80,
            "blockers": [
                "check_failed:pytest",
            ],
            "files_changed": [
                "backend/tests/test_x.py",
            ],
            "checks": [
                {
                    "type": "pytest",
                    "status": "FAIL",
                    "returncode": 1,
                    "output": (
                        "FAILED test_x.py::test_x\\n"
                        "E   AssertionError: expected R2\\n"
                    ),
                },
            ],
            "production_touched": False,
            "arbitrary_private_payload": {
                "do_not_export": "PRIVATE"
            },
        },
    )

    monkeypatch.setattr(
        detail,
        "RESULTS",
        results,
    )

    report = detail.collect(
        SOURCE_JOB
    )

    assert report["status"] == "PASS"
    assert report["result_status"] == (
        "GIT_TESTS_FAILED"
    )
    assert report["failed_check_count"] == 1
    assert report["failed_checks"][0][
        "type"
    ] == "pytest"

    assert (
        "AssertionError"
        in report["failed_checks"][0][
            "output"
        ]
    )

    serialized = json.dumps(report)

    assert "PRIVATE" not in serialized
    assert (
        "arbitrary_private_payload"
        not in serialized
    )


def test_detail_reader_redacts_sensitive_output(
    tmp_path,
    monkeypatch,
):
    results = tmp_path / "results"

    fake_secret = (
        "tok"
        "en=FICTITIOUS_SECRET_123456"
    )

    _write_result(
        results,
        {
            "status": "GIT_TESTS_FAILED",
            "checks": [
                {
                    "type": "pytest",
                    "status": "FAIL",
                    "returncode": 1,
                    "output": (
                        "normal line\\n"
                        + fake_secret
                        + "\\n"
                    ),
                },
            ],
            "production_touched": False,
        },
    )

    monkeypatch.setattr(
        detail,
        "RESULTS",
        results,
    )

    report = detail.collect(
        SOURCE_JOB
    )

    serialized = json.dumps(report)

    assert "FICTITIOUS_SECRET_123456" not in serialized
    assert "[REDACTED]" in serialized


def test_detail_reader_rejects_arbitrary_identifier():
    with pytest.raises(
        ValueError,
        match="RESULT_DETAIL_JOB_ID_INVALID",
    ):
        detail.collect("../../etc/passwd")


def test_detail_check_is_strictly_bounded():
    check = {
        "type": "worker_result_detail_read",
        "request": {
            "job_id": SOURCE_JOB,
        },
    }

    assert bridge.validate_check(
        check,
        0,
    ) == []

    assert bridge.validate_check(
        {
            **check,
            "path": "/etc/passwd",
        },
        0,
    )

    assert bridge.validate_check(
        {
            "type": "worker_result_detail_read",
            "request": {
                "job_id": SOURCE_JOB,
                "path": "/etc/passwd",
            },
        },
        0,
    )

    assert (
        "worker_result_detail_read"
        in bridge.READ_ONLY_CHECKS
    )

    assert (
        "worker_result_detail_read"
        in bridge.ALLOWED_CHECKS
    )

    assert (
        "worker_result_detail_read"
        in publisher.ALLOWED_CHECKS
    )


def test_detail_semantic_capability_registered():
    assert (
        "WORKER_RESULT_DETAIL_READ"
        in registered_capabilities()
    )


def test_detail_semantic_expansion_is_read_only():
    job = service.build_semantic_job(
        {
            "objective": (
                "Leer detalle sanitizado "
                "de resultado Worker."
            ),
            "bounded_context": "WORKER_REPAIR",
            "mode": "READ_ONLY",
            "capability": (
                "WORKER_RESULT_DETAIL_READ"
            ),
            "constraints": {
                "source_job_id": SOURCE_JOB,
            },
        },
        current_user={
            "id": "1",
            "email": "admin@example.com",
            "role": "SuperAdministrador",
        },
    )

    assert job["mode"] == "READ_ONLY"
    assert job["actions"] == []
    assert job["production_allowed"] is False

    assert job["checks"] == [
        {
            "type": "worker_result_detail_read",
            "request": {
                "job_id": SOURCE_JOB,
            },
        }
    ]


def test_detail_capability_rejects_extra_constraints():
    with pytest.raises(
        service.WorkerIngressError,
        match="SEMANTIC_CONSTRAINTS_UNSUPPORTED",
    ):
        service.build_semantic_job(
            {
                "objective": "Read failure.",
                "bounded_context": "WORKER_REPAIR",
                "mode": "READ_ONLY",
                "capability": (
                    "WORKER_RESULT_DETAIL_READ"
                ),
                "constraints": {
                    "source_job_id": SOURCE_JOB,
                    "path": "/etc/passwd",
                },
            },
            current_user={
                "id": "1",
                "email": "admin@example.com",
                "role": "SuperAdministrador",
            },
        )


def test_dispatcher_registers_detail_evidence():
    dispatcher = (
        Path(__file__)
        .resolve()
        .parents[2]
        / "tools"
        / "mirror_sync"
        / "universal_job_dispatcher.py"
    )

    source = dispatcher.read_text(
        encoding="utf-8"
    )

    assert (
        'elif kind == "worker_result_detail_read":'
        in source
    )

    assert (
        'response["result_detail_evidence"]'
        in source
    )
